# CORS for the MCP and OAuth endpoints (generated by maquina:mcp).
#
# Browser-based MCP clients, such as the MCP Inspector, run discovery, the
# token exchange and the MCP calls with fetch() from their own origin.
# Without these headers discovery "works" but its answer is blocked, and the
# client quietly falls back to default endpoints that do not exist.
#
# The wildcard origin is safe only because none of these paths use cookies:
# never add Access-Control-Allow-Credentials. /oauth/authorize is left out on
# purpose; it is a top-level page on the signed-in session.
#
# It sits at position 0 so a preflight is answered before host authorization
# or anything else sees it. Middleware does not reload: restart after editing.
class McpCors
  PATHS = %r{\A/(?:mcp\z|oauth/(?:token|revoke)\z|\.well-known/oauth-)}
  HEADERS = {
    "access-control-allow-origin" => "*",
    "access-control-allow-methods" => "GET, POST, DELETE, OPTIONS",
    "access-control-allow-headers" => "Authorization, Content-Type, MCP-Protocol-Version, Mcp-Method, Mcp-Name",
    "access-control-expose-headers" => "WWW-Authenticate",
    "access-control-max-age" => "86400"
  }.freeze

  def initialize(app)
    @app = app
  end

  def call(env)
    return @app.call(env) unless PATHS.match?(env["PATH_INFO"].to_s)
    return [204, HEADERS.dup, []] if env["REQUEST_METHOD"] == "OPTIONS"

    status, headers, body = @app.call(env)
    HEADERS.each { |name, value| headers[name] = value }
    [status, headers, body]
  end
end

Rails.application.config.middleware.insert_before 0, McpCors
